$LanguageNames = @{ fr='Français'; en='English'; de='Deutsch'; es='Español'; zh='中文' }

function Resolve-InstallerLanguage([string]$Path,[string]$Requested) {
    if ($Requested -in @('fr','en','de','es','zh')) { return $Requested }
    try {
        if ($Path) {
            $existing = Join-Path $Path 'config\rfpy.json'
            if (Test-Path -LiteralPath $existing) {
                $cfg = Get-Content -LiteralPath $existing -Raw -Encoding UTF8 | ConvertFrom-Json
                if ($cfg.ui.language -in @('fr','en','de','es','zh')) { return [string]$cfg.ui.language }
            }
        }
    } catch { }
    try {
        $code = [Globalization.CultureInfo]::CurrentUICulture.TwoLetterISOLanguageName.ToLowerInvariant()
        if ($code -in @('fr','en','de','es','zh')) { return $code }
    } catch { }
    return 'en'
}

function Get-ExistingWebPort([string]$Path) {
    try {
        if ($Path) {
            $existing = Join-Path $Path 'config\rfpy.json'
            if (Test-Path -LiteralPath $existing) {
                $cfg = Get-Content -LiteralPath $existing -Raw -Encoding UTF8 | ConvertFrom-Json
                if ($null -ne $cfg.web -and $null -ne $cfg.web.port) {
                    $p=[int]$cfg.web.port
                    if ($p -ge 0 -and $p -le 65535) { return $p }
                }
            }
        }
    } catch { }
    return 0
}

trap {
    $m = [string]$_.Exception.Message
    if ([string]::IsNullOrWhiteSpace($m)) { $m = 'RFPY installer error.' }
    Write-Host "`n[ERROR] $m" -ForegroundColor Red
    exit 1
}

$LongOptions = @{
    '--install-dir' = @{Name='InstallDir'; Switch=$false}
    '--language' = @{Name='Language'; Switch=$false}
    '--web-port' = @{Name='WebPort'; Switch=$false}
    '--uv-version' = @{Name='UvVersion'; Switch=$false}
    '--tool-python' = @{Name='ToolPythonVersion'; Switch=$false}
    '--tool-python-version' = @{Name='ToolPythonVersion'; Switch=$false}
    '--proxy-url' = @{Name='ProxyUrl'; Switch=$false}
    '--uv-url' = @{Name='UvUrl'; Switch=$false}
    '--no-path' = @{Name='NoPath'; Switch=$true}
    '--launch-web' = @{Name='LaunchWeb'; Switch=$true}
    '--help' = @{Name='Help'; Switch=$true}
}
$tokens = [System.Collections.Generic.List[object]]::new()
if ($InstallDir -match '^-[A-Za-z][A-Za-z0-9-]{2,}(?:=.*)?$') {
    $candidate = '--' + $InstallDir.Substring(1)
    $candidateName = (($candidate -split '=',2)[0]).ToLowerInvariant()
    if ($LongOptions.ContainsKey($candidateName)) { $tokens.Add($InstallDir); $InstallDir=''; $InstallDirExplicit=$false }
}
foreach ($a in @($RemainingArgs)) { $tokens.Add($a) }
for ($ix=0; $ix -lt $tokens.Count; $ix++) {
    $token = ([string]$tokens[$ix]).Trim(); if ([string]::IsNullOrWhiteSpace($token)) { continue }
    if ($token -match '^-[A-Za-z][A-Za-z0-9-]{2,}(?:=.*)?$') {
        $candidate='--'+$token.Substring(1); $candidateName=(($candidate -split '=',2)[0]).ToLowerInvariant()
        if ($LongOptions.ContainsKey($candidateName)) { $token=$candidate }
    }
    $inline=$null; $name=$token
    if ($token -match '^(--[^=]+)=(.*)$') { $name=$Matches[1]; $inline=$Matches[2] }
    $key=$name.ToLowerInvariant(); if (-not $LongOptions.ContainsKey($key)) { throw "Unknown parameter: $token" }
    $spec=$LongOptions[$key]
    if ($spec.Switch) { Set-Variable -Name $spec.Name -Value $true -Scope Script; continue }
    $value=$inline
    if ($null -eq $value) { $ix++; if ($ix -ge $tokens.Count) { throw "Missing value for $name" }; $value=[string]$tokens[$ix] }
    Set-Variable -Name $spec.Name -Value $value -Scope Script
    if ($spec.Name -eq 'InstallDir') { $InstallDirExplicit=$true }
}

function Show-Help {
    $lang = Resolve-InstallerLanguage -Path $(if($InstallDir){$InstallDir}else{'C:\RFPY'}) -Requested $Language
    Write-Host (($InstallerWords[$lang].installerHeader) -f $InstallerVersion) -ForegroundColor Cyan
    Write-Host ''
    Write-Host '  -i,  --install-dir <path>       Installation root (native dialog if omitted)'
    Write-Host '  -l,  --language <code>          fr | en | de | es | zh'
    Write-Host '  -wp, --web-port <0|port>        0=automatic, otherwise fixed port'
    Write-Host '  -u,  --uv-version <version>     uv version'
    Write-Host '  -tp, --tool-python <version>    RFPY manager Python'
    Write-Host '  -px, --proxy-url <url>          Initial optional proxy'
    Write-Host '  -uu, --uv-url <url>             Alternative uv ZIP URL'
    Write-Host '  -np, --no-path                  Do not update user PATH'
    Write-Host '  -w,  --launch-web               Open Web UI after installation'
    Write-Host '  -h,  --help                     Help'
    Write-Host "  language: $($LanguageNames[$lang]) ($lang)"
}

function Get-RfpyDialogIcon {
    try {
        $exe = [Diagnostics.Process]::GetCurrentProcess().MainModule.FileName
        $hostName = if ($exe) { [IO.Path]::GetFileNameWithoutExtension($exe).ToLowerInvariant() } else { '' }
        # Sous PS2EXE, l'exécutable courant porte l'icône RFPY. Lors d'une
        # exécution directe du .ps1, ignorer l'icône powershell/pwsh et utiliser
        # l'asset RFPY du dépôt à la place.
        if ($exe -and $hostName -notin @('powershell','pwsh','powershell_ise') -and (Test-Path -LiteralPath $exe) -and ([IO.Path]::GetExtension($exe) -ieq '.exe')) {
            return [Drawing.Icon]::ExtractAssociatedIcon($exe)
        }
    } catch { }
    try {
        $candidate = Join-Path (Split-Path -Parent $PSScriptRoot) 'assets\rfpy.ico'
        if (Test-Path -LiteralPath $candidate) { return New-Object Drawing.Icon($candidate) }
    } catch { }
    return $null
}

function New-RfpyGlobeBitmap {
    $bmp = New-Object Drawing.Bitmap 20,20
    $g = [Drawing.Graphics]::FromImage($bmp)
    $g.SmoothingMode = [Drawing.Drawing2D.SmoothingMode]::AntiAlias
    $pen = New-Object Drawing.Pen([Drawing.Color]::FromArgb(0,120,215), 1.5)
    try {
        $g.DrawEllipse($pen, 2,2,16,16)
        $g.DrawEllipse($pen, 6,2,8,16)
        $g.DrawEllipse($pen, 2,6,16,8)
    } finally {
        $pen.Dispose(); $g.Dispose()
    }
    return $bmp
}

