    $langButton.ImageAlign=[Drawing.ContentAlignment]::MiddleLeft; $langButton.TextImageRelation=[Windows.Forms.TextImageRelation]::ImageBeforeText; $langButton.Padding=New-Object Windows.Forms.Padding(7,0,4,0)
