    $portBox = New-Object System.Windows.Forms.NumericUpDown
    $portBox.Location=New-Object Drawing.Point(350,128); $portBox.Size=New-Object Drawing.Size(95,25); $portBox.Minimum=1; $portBox.Maximum=65535; $portBox.Value=$(if($DefaultWebPort -gt 0){$DefaultWebPort}else{8765}); $portBox.Enabled=(-not $portAuto.Checked); $form.Controls.Add($portBox)
    $portHint = New-Object System.Windows.Forms.Label
    $portHint.AutoSize=$true; $portHint.ForeColor=[Drawing.Color]::DimGray; $portHint.Font=New-Object Drawing.Font('Segoe UI',8); $portHint.Location=New-Object Drawing.Point(20,158); $form.Controls.Add($portHint)
    $portAuto.Add_CheckedChanged({ $portBox.Enabled=(-not $portAuto.Checked) })

