$escapedRootPs = $InstallDir.Replace("'", "''")

# IMPORTANT : rfpy.ps1 contient des traductions FR/EN/DE/ES/ZH.
# Ne jamais le relire avec Get-Content sans encodage sous Windows PowerShell 5.1 /
# PS2EXE : le UTF-8 serait interprété avec la page de codes ANSI puis réécrit
# sous forme de mojibake. Lire explicitement en UTF-8 et écrire avec BOM pour
# rester compatible PowerShell 5.1 et PowerShell 7.
$utf8NoBom = [Text.UTF8Encoding]::new($false)
$utf8Bom   = [Text.UTF8Encoding]::new($true)
$psContent = [IO.File]::ReadAllText($rfpyPsPath, $utf8NoBom)
$psContent = $psContent.Replace("'__RFPY_ROOT__'", "'$escapedRootPs'")
[IO.File]::WriteAllText($rfpyPsPath, $psContent, $utf8Bom)
$webPsContent = [IO.File]::ReadAllText($rfpyWebPsPath, $utf8NoBom)
$webPsContent = $webPsContent.Replace("'__RFPY_ROOT__'", "'$escapedRootPs'")
[IO.File]::WriteAllText($rfpyWebPsPath, $webPsContent, $utf8Bom)

